export {makeHero,animateHero} from './character.mjs';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
const mats=new Map();function mat(c,metal=0){const key=c+':'+metal;if(!mats.has(key))mats.set(key,new T.MeshStandardMaterial({color:c,map:(['#e6ba83','#dba374','#e6c998','#cfb78e','#efd4a0'].includes(c)?surface('plaster',2,2):['#8f5834','#bf864e','#855534','#9a6843','#765033','#513a2a'].includes(c)?surface('wood',1,2):null),roughness:.78,metalness:metal}));return mats.get(key)}
const sphere=new T.SphereGeometry(1,12,9),box=new T.BoxGeometry(1,1,1),cylinder=new T.CylinderGeometry(1,1,1,12),cone=new T.ConeGeometry(1,1,12);
function mesh(g,geo,c,x,y,z,sx=1,sy=1,sz=1){let m=new T.Mesh(geo,mat(c));m.position.set(x,y,z);m.scale.set(sx,sy,sz);g.add(m);return m}
const ball=(g,c,x,y,z,sx,sy=sx,sz=sx)=>mesh(g,sphere,c,x,y,z,sx,sy,sz);
const cube=(g,c,x,y,z,sx,sy,sz)=>mesh(g,box,c,x,y,z,sx,sy,sz);
const cyl=(g,c,x,y,z,sx,sy,sz=sx)=>mesh(g,cylinder,c,x,y,z,sx,sy,sz);
function bake(g){g.updateMatrixWorld(true);const groups=new Map();g.traverse(m=>{if(m.isMesh){const geo=m.geometry.clone().applyMatrix4(m.matrixWorld);if(!groups.has(m.material))groups.set(m.material,[]);groups.get(m.material).push(geo)}});const out=new T.Group();for(const [material,geos]of groups){const m=new T.Mesh(mergeGeometries(geos,false),material);m.receiveShadow=true;out.add(m);geos.forEach(x=>x.dispose())}return out}
function flower(g,x,y,z,c='#efaf36',s=.2){ball(g,c,x,y,z,s,s*.7,s);ball(g,'#ffe6a1',x,y+s*.5,z,s*.35)}
function pot(g,x,y,z,s=1){ball(g,'#b55a36',x,y+.38*s,z,.39*s,.43*s,.39*s);cyl(g,'#e8b36b',x,y+.75*s,z,.26*s,.09*s);cyl(g,'#783e2c',x,y+.8*s,z,.21*s,.03*s)}
const leafGeo=new T.SphereGeometry(1,6,4);
function leafCluster(g,x,y,z,seed=0){for(let i=0;i<7;i++){const a=i*2.4+seed;let m=mesh(g,leafGeo,['#397c3b','#559f43','#86b84c'][i%3],x+Math.cos(a)*.3,y+Math.sin(a*2)*.22,z+Math.sin(a)*.3,.25,.045,.12);m.rotation.set(Math.sin(a),a,.4);}}
function tree(g,x,z,variant=0){cyl(g,'#765033',x,2.1,z,.25,4.2);for(let i=0;i<5;i++){const a=i*2.4+variant,xx=x+Math.cos(a)*1.05,zz=z+Math.sin(a)*1.05;let br=cyl(g,'#765033',(x+xx)/2,3.5, (z+zz)/2,.09,2);br.rotation.z=Math.cos(a)*.65;br.rotation.x=Math.sin(a)*.65;for(let j=0;j<7;j++)leafCluster(g,xx+Math.cos(j*2.4)*.65,4+Math.sin(j*1.3)*.65,zz+Math.sin(j*2.4)*.65,j);}}
function building(g,x,z,variant){let c=['#e6ba83','#dba374','#e6c998'][variant%3],h=5+variant%3;cube(g,c,x,h/2,z,3.6,h,6);for(let y of [0.25,2.8,h])cube(g,'#f3d3a1',x,y,z,3.95,.18,6.25);for(let j=-1;j<=1;j++){let zz=z+j*1.7;cube(g,'#295951',x+1.83,1.6,zz,.07,1.7,.8);ball(g,'#295951',x+1.84,2.45,zz,.04,.5,.4);cube(g,'#e8c08b',x+1.95,1.1,zz,.2,.13,1.05);cube(g,'#47776b',x+1.84,4.2,zz,.1,1.25,.7);ball(g,'#47776b',x+1.84,4.8,zz,.06,.35,.35);for(let k=0;k<4;k++)flower(g,x+2.03,3.1+Math.sin(k)*.09,zz-.5+k*.3,k%2?'#e89232':'#f3bd46',.17)}for(let j=-1;j<=1;j++){const zz=z+j*1.7;cube(g,'#bf864e',x+2.12,3.52,zz,.65,.12,1.18);for(let k=0;k<5;k++)cyl(g,'#855534',x+2.4,3.83,zz-.48+k*.24,.025,.55);cube(g,'#bf864e',x+2.4,4.12,zz,.07,.08,1.2);cube(g,'#ba6b48',x+2.12,5.14,zz,1,.12,1.35);for(let k=0;k<3;k++){const v=cube(g,'#c0a174',x+1.89,4.3,zz-.24+k*.24,.09,.94,.035);}}for(let j=0;j<9;j++)cube(g,'#f3d3a1',x+1.75,h+.25,z-2.8+j*.7,.35,.5,.4);for(let j=0;j<10;j++){const zz=z-2.8+j*.6;leafCluster(g,x+1.98,2.95,zz,j);if(j%2===0)flower(g,x+2.18,3.06,zz,'#f35a91',.15);} cube(g,'#ba6b48',x+2.2,2.85,z,1.2,.15,5.3);for(let j=-2;j<=2;j++)cyl(g,'#e2bb81',x+2.65,1.5,z+j,.06,2.8);for(let k=0;k<7;k++)ball(g,k%2?'#ecb240':'#f4d063',x+2.8,2.75-Math.sin(k/6*Math.PI)*.45,z-2.5+k*.82,.19);for(let k=-1;k<2;k++){pot(g,x+2.3,.1,z+k*1.7,.7);for(let j=0;j<3;j++)flower(g,x+2.3+(j-1)*.22,.85,z+k*1.7,'#eb6d83',.16)} }
function temple(g,x,z,s=1){cube(g,'#cfb78e',x,2*s,z,4*s,4*s,4*s);for(let i=0;i<4;i++)cube(g,'#efd4a0',x,(4+i*.7)*s,z,(4-i*.6)*s,.4*s,(4-i*.6)*s);mesh(g,cone,'#e1c295',x,7*s,z,1.5*s,3*s,1.5*s);ball(g,'#efbd58',x,8.6*s,z,.2*s);cyl(g,'#e1ad4c',x,9*s,z,.04*s,1*s);let flag=cube(g,'#dc8450',x+.4*s,9.35*s,z,.75*s,.35*s,.04*s);flag.rotation.z=.12;cube(g,'#506d60',x,1.4*s,z+2.01*s,1.2*s,2.8*s,.03)}
function featherGeometry(){const shape=new T.Shape();shape.moveTo(0,-.65);shape.bezierCurveTo(-.5,-.2,-.46,.6,0,.85);shape.bezierCurveTo(.46,.6,.5,-.2,0,-.65);return new T.ShapeGeometry(shape)}
export function makeCoin(){const g=new T.Group();const face=new T.Mesh(new T.CylinderGeometry(.27,.27,.07,24),new T.MeshStandardMaterial({color:'#ffc638',metalness:.7,roughness:.27,emissive:'#b77b06',emissiveIntensity:.22}));face.rotation.x=Math.PI/2;g.add(face);const border=new T.Mesh(new T.TorusGeometry(.235,.018,6,24),mat('#ffe9a0',.5));border.position.z=.05;g.add(border);ball(g,'#e69b18',0,-.015,.063,.11,.1,.028);cube(g,'#fff0af',0,.085,.065,.14,.035,.035);return g;}
export function makeFeather(){const g=new T.Group();const m=new T.Mesh(featherGeometry(),new T.MeshStandardMaterial({color:'#4ed5a1',emissive:'#147653',emissiveIntensity:.5,side:T.DoubleSide,roughness:.4}));g.add(m);for(const [c,s,z]of [['#eccc62',.23,.025],['#208baa',.17,.04],['#143876',.105,.055]])ball(g,c,0,.25,z,s,s*1.25,.035);cube(g,'#e4ca75',0,-.25,.01,.025,.85,.025);return g}
function obstacle(type){const g=new T.Group();if(type==='cart'){cube(g,'#8f5834',0,.65,0,1.8,.2,1.3);for(let i=0;i<5;i++)cube(g,'#bf864e',-.78+i*.39,.86,0,.3,.25,1.15);for(let x of [-.95,.95])for(let z of [-.5,.5]){let w=cyl(g,'#513a2a',x,.4,z,.36,.15);w.rotation.z=Math.PI/2;let hub=cyl(g,'#d6aa66',x*1.09,.4,z,.12,.02);hub.rotation.z=Math.PI/2;}for(let x of [-.5,.5])pot(g,x,.95,0,.65);flower(g,0,1.25,.15,'#ebc250',.26);}else{for(let x of [-1,1]){cube(g,'#9a6843',x,1.7,0,.15,3.4,.2);cube(g,'#e9bd79',x,.35,0,.28,.4,.3);}cube(g,'#855534',0,2.45,0,2.35,.85,.3);for(let i=0;i<8;i++)flower(g,-1+i*.29,2.14-Math.sin(i/7*Math.PI)*.25,.22,i%2?'#f2d16a':'#ed9651',.17);for(let i=0;i<5;i++)ball(g,'#44815b',-.9+i*.45,2.9,0,.29,.1,.23);}
 return bake(g)}
export class World{
 constructor(canvas,quality='high'){this.qualityMode=quality;this.slowFrames=0;this.performanceFrames=0;this.scene=new T.Scene();this.scene.background=new T.Color('#a9dcf1');this.scene.fog=new T.Fog('#a9dcf1',38,155);this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,quality==='low'?1:1.5));this.renderer.shadowMap.enabled=quality!=='low';this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.05;this.camera=new T.PerspectiveCamera(54,1,.1,230);this.scene.add(new T.HemisphereLight('#fff1c9','#506d54',2.4));const sun=new T.DirectionalLight('#ffdfad',3.2);sun.position.set(-12,25,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-12;sun.shadow.camera.right=12;sun.shadow.camera.top=17;sun.shadow.camera.bottom=-20;sun.shadow.normalBias=.04;this.scene.add(sun);this.hero=makeHero();this.heroes=new Map([['krishna',this.hero]]);const aura=new T.Mesh(new T.SphereGeometry(1,24,16),new T.MeshBasicMaterial({color:'#71d8ff',transparent:true,opacity:.15,side:T.FrontSide,depthWrite:false}));aura.scale.set(.8,1.45,.8);aura.visible=false;this.aura=aura;this.scene.add(aura);this.hero.position.set(0,0,2);this.scene.add(this.hero);this.danav=makeDanav();this.danav.position.set(0,0,-18);this.scene.add(this.danav);this.mala=new T.Group();for(let i=0;i<24;i++){const a=i/24*Math.PI*2;ball(this.mala,i%3?'#fff3cf':'#f2a42d',Math.cos(a)*.22,Math.sin(a)*.33,0,.04,.045,.038);}this.scene.add(this.mala);this.danav.userData.pot.visible=false;this.templates={coin:makeCoin(),glide:makeFeather(),shield:this.powerPickup('#419cfb','shield'),magnet:this.powerPickup('#ed5368','magnet'),cart:obstacle('cart'),arch:obstacle('arch')};this.objects=new Map();this.objectPool=new Map();this.chunks=[];this.stage=0;this.time=0;this.travel=0;this.menuBlend=1;this.particles=[];this.sparkGeometry=new T.OctahedronGeometry(.045);this.sparkMaterial=new T.MeshBasicMaterial({color:'#ffe596'});this.makeEnvironment();this.resize();}
 powerPickup(color,type){const g=new T.Group();if(type==='magnet'){const arc=new T.Mesh(new T.TorusGeometry(.28,.085,8,24,Math.PI),mat('#ec4b59',.3));arc.rotation.z=Math.PI;g.add(arc);for(const side of [-1,1]){cube(g,'#ec4b59',side*.28,.13,0,.17,.28,.17);cube(g,'#d9efff',side*.28,.29,0,.17,.13,.17);}}else{const sh=new T.Shape();sh.moveTo(-.32,.36);sh.lineTo(.32,.36);sh.lineTo(.29,-.06);sh.quadraticCurveTo(.18,-.31,0,-.43);sh.quadraticCurveTo(-.18,-.31,-.29,-.06);sh.closePath();const shield=new T.Mesh(new T.ExtrudeGeometry(sh,{depth:.075,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:2,steps:1}),mat('#368bdc',.4));g.add(shield);const star=new T.Mesh(new T.OctahedronGeometry(.14),mat('#fff0a0',.6));star.position.set(0,.03,.13);star.scale.z=.3;g.add(star);}const halo=new T.Mesh(new T.TorusGeometry(.53,.023,6,32),mat('#ffda75',.5));g.add(halo);return g;}

 resize(){const w=Math.max(1,this.renderer.domElement.clientWidth),h=Math.max(1,this.renderer.domElement.clientHeight);this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix()}
 character(name){this.scene.remove(this.hero);if(!this.heroes.has(name))this.heroes.set(name,makeHero(name));this.hero=this.heroes.get(name);this.hero.position.z=2;this.scene.add(this.hero)}
 portrait(name){
 this.portraits??=new Map();if(this.portraits.has(name))return this.portraits.get(name);
 if(!this.heroes.has(name))this.heroes.set(name,makeHero(name));const hero=this.heroes.get(name),parent=hero.parent,position=hero.position.clone(),rotation=hero.rotation.clone();
 const scene=new T.Scene();scene.background=new T.Color('#183e68');scene.add(new T.HemisphereLight('#fff4df','#6080a4',2.4));const key=new T.DirectionalLight('#ffedcd',2);key.position.set(-3,5,4);scene.add(key);scene.add(hero);hero.position.set(0,0,0);hero.rotation.set(0,Math.PI,0);animateHero(hero,0,{running:false,dt:0});
 const camera=new T.PerspectiveCamera(31,1,.1,20);camera.position.set(0,1.98,3.3);camera.lookAt(0,1.92,0);
 const target=new T.WebGLRenderTarget(160,160),prior=this.renderer.getRenderTarget();const pixels=new Uint8Array(160*160*4);
 try{this.renderer.setRenderTarget(target);this.renderer.render(scene,camera);this.renderer.readRenderTargetPixels(target,0,0,160,160,pixels);}finally{this.renderer.setRenderTarget(prior);target.dispose();scene.remove(hero);if(parent)parent.add(hero);hero.position.copy(position);hero.rotation.copy(rotation);}
 const canvas=document.createElement('canvas');canvas.width=canvas.height=160;const ctx=canvas.getContext('2d'),frame=ctx.createImageData(160,160);for(let y=0;y<160;y++)frame.data.set(pixels.subarray((159-y)*640,(160-y)*640),y*640);ctx.putImageData(frame,0,0);const url=canvas.toDataURL('image/png');this.portraits.set(name,url);return url;
 }
 releaseObject(m){this.scene.remove(m);const type=m.userData.kind;if(!type)return;if(!this.objectPool.has(type))this.objectPool.set(type,[]);const pool=this.objectPool.get(type);if(pool.length<40)pool.push(m);}
 quality(q){this.qualityMode=q;this.slowFrames=0;this.performanceFrames=0;this.renderer.setPixelRatio(Math.min(devicePixelRatio,q==='low'?1:1.5));this.renderer.shadowMap.enabled=q!=='low';this.resize()}
 makeEnvironment(){
 const roadMat=new T.MeshStandardMaterial({map:surface('stone',3,6),color:'#fff2dc',roughness:.95});
 const water=new T.Mesh(new T.PlaneGeometry(240,240),new T.MeshStandardMaterial({color:'#489d9e',roughness:.35,metalness:.2}));water.rotation.x=-Math.PI/2;water.position.set(100,-.6,-80);this.scene.add(water);this.water=water;
 const horizon=new T.Group();for(let i=0;i<6;i++)temple(horizon,30+i*10,-80-(i%3)*10,1+i%2*.5);this.scene.add(bake(horizon));const sunDisk=new T.Mesh(new T.SphereGeometry(5,20,12),new T.MeshBasicMaterial({color:'#ffefbe'}));sunDisk.position.set(45,34,-140);this.scene.add(sunDisk);
 for(let i=0;i<10;i++){let base=new T.Group();let road=new T.Mesh(new T.BoxGeometry(9,.2,18),roadMat);road.position.y=-.13;road.receiveShadow=true;base.add(road);const decor=new T.Group();for(let side of [-1,1]){cube(decor,'#507c3c',side*7,-.14,0,5,.15,18);for(let j=0;j<9;j++)leafCluster(decor,side*(4.9+(j%2)*.3),.2,-8+j*2,j);}for(let x of [-4.45,4.45]){cube(decor,'#e7cc9b',x,.04,0,.16,.1,18);for(let j=-8;j<9;j+=3){cube(decor,'#e5c48d',x,.55,j,.32,1.1,.32);ball(decor,'#e8ca93',x,1.15,j,.23,.14,.23)}cube(decor,'#d6b77f',x,.9,0,.15,.13,18);}for(let x of [-1.275,1.275])cube(decor,'#b7a27a',x,-.017,0,.026,.015,18);base.add(bake(decor));const village=new T.Group();building(village,-7.2,0,i);if(i%2===0)tree(village,-9,-5,i);this.addLantern(village,-4.05,-6);base.add(bake(village));const right=new T.Group();if(i%3!==0){const facade=new T.Group();building(facade,-7.4,0,i+1);facade.rotation.y=Math.PI;right.add(facade);}tree(right,9.5,-3,i);for(let f=0;f<14;f++){let z=-8+f*1.2;flower(right,4.8+(f%3)*.18,.25,z,f%2?'#ec5593':'#ffc33f',.15);}for(let j=0;j<5;j++)flower(right,5.2+j*.3,.2,3+j*.6,j%2?'#e79b83':'#edc165',.22);if(i%3===0){pot(right,5.8,0,2,1.2);temple(right,13,2,.55)}base.add(bake(right));const forest=new T.Group();tree(forest,-6,-4,i);tree(forest,6,4,i+2);for(let j=0;j<4;j++){ball(forest,'#657b65',-5.3,.3,-7+j*4,.65,.4,.8);ball(forest,'#657b65',5.3,.3,-5+j*4,.5,.5,.7);}const fmesh=bake(forest);fmesh.visible=false;base.add(fmesh);const ghat=new T.Group();for(let j=0;j<5;j++)cube(ghat,'#cfb78e',5.2+j*.6,-.15-j*.15,0,.65,.25,18);for(let j of [-6,3]){this.addLantern(ghat,4.7,j);pot(ghat,5.1,-.1,j,.8);}const gh=bake(ghat);gh.visible=false;base.add(gh);base.userData={forest:fmesh,ghat:gh};base.position.z=-i*18;this.scene.add(base);this.chunks.push(base);}
 // Overhead flower strings, set well above the playable lane.
 const fest=new T.Group();for(let k=0;k<3;k++){for(let j=0;j<15;j++){let x=-4.5+j*9/14;flower(fest,x,5.5-Math.sin(j/14*Math.PI)*1.1,-k*48,j%2?'#f0bd4e':'#e8905a',.15);}}this.fest=bake(fest);this.scene.add(this.fest);
 const pos=new Float32Array(80*3);for(let i=0;i<80;i++){pos[i*3]=(Math.random()-.5)*19;pos[i*3+1]=Math.random()*7;pos[i*3+2]=-Math.random()*100;}const geom=new T.BufferGeometry();geom.setAttribute('position',new T.BufferAttribute(pos,3));this.dust=new T.Points(geom,new T.PointsMaterial({color:'#fff4bd',size:.075,transparent:true,opacity:.7}));this.scene.add(this.dust);
 }
 addLantern(g,x,z){cyl(g,'#625e3e',x,1.8,z,.045,3.6);cube(g,'#615b3d',x,3.6,z,.4,.1,.4);ball(g,'#ffd08b',x,3.33,z,.13,.24,.13);cube(g,'#6d6547',x,3.08,z,.3,.07,.3);}
 setStage(n){this.stage=n;const colors=['#a9dcf1','#f2c6aa','#a6cbb2'];this.scene.background.set(colors[n]);this.scene.fog.color.set(colors[n]);this.water.material.color.set(n===1?'#4aa8b4':n===2?'#477e76':'#489d9e');for(const chunk of this.chunks){chunk.children[2].visible=n!==2;chunk.children[3].visible=n===0;chunk.userData.forest.visible=n===2;chunk.userData.ghat.visible=n===1;}}
 clear(){this.menuBlend=0;this.hero.rotation.y=0;this.hero.userData.slideBlend=0;for(const m of this.objects.values())this.releaseObject(m);this.objects.clear();for(const p of this.particles)this.scene.remove(p.m);this.particles=[];this.travel=0;this.setStage(0);}
 update(dt,run,menu=false){this.time+=dt;let t=this.time;const intro=run?.intro||0;let speed=menu?3:run?.state==='running'&&!intro?run.speed:0;this.travel+=speed*dt;for(let i=0;i<this.chunks.length;i++)this.chunks[i].position.z=((this.travel+i*18)%180)-150;this.fest.position.z=this.travel%48;this.dust.rotation.z=Math.sin(t*.2)*.02;this.menuBlend=T.MathUtils.damp(this.menuBlend,menu?1:0,4,dt);const b=Math.max(this.menuBlend,intro?Math.min(1,Math.max(0,(intro-1)/1.5)):0);frameCamera(this.camera,{x:run?.x||0,menuBlend:b,showcase:this.menuLayout==='characters'||intro>0});this.hero.position.x=menu?0:(run?.x||0);this.hero.rotation.y=menu?Math.PI+.08:intro?Math.PI*Math.min(1,Math.max(0,(intro-1.7)/.8)):T.MathUtils.damp(this.hero.rotation.y,0,12,dt);this.hero.rotation.z=menu?0:T.MathUtils.clamp(((run?.lane||0)*2.55-this.hero.position.x)*-.12,-.2,.2);this.hero.visible=true;animateHero(this.hero,t,{jump:menu?0:run?.jump||0,slide:menu?0:run?.slide||0,glide:menu?0:run?.glide||0,glideHeight:menu?0:run?.glideHeight||0,running:!menu&&!intro&&run?.state==='running',dt,speed:run?.speed||12});
 this.aura.visible=!menu&&(run?.shield>0||run?.invincible>0);this.aura.material.opacity=run?.shield>0?.15:.09+.04*Math.sin(t*18);this.aura.position.set(this.hero.position.x,1.2+(run?.jump||0),2);this.aura.rotation.y=t*.5;this.danav.visible=!menu;this.danav.position.x=Math.sin(t*.8)*2.1;this.danav.position.z=run?.catchAnimation>0?-7-(1.8-run.catchAnimation)*15:-19+Math.min(9,(run?.chaseFeathers||0)*.6);this.danav.rotation.y=Math.sin(t*.7)*.15;if(intro){const elapsed=4-intro;if(elapsed<1.5){this.danav.position.set(2.1-elapsed*1.1,0,2.2);this.danav.rotation.y=Math.PI;this.danav.userData.limbs[0].arm.rotation.z=-.5;}else{const escape=(elapsed-1.5)/2.5;this.danav.position.set(.45*(1-escape),0,2-21*escape);this.danav.rotation.y=0;}}animateDanav(this.danav,t,run?.catchAnimation||0);if(intro>2.5)this.danav.userData.limbs[0].arm.rotation.x=-1.4;this.mala.visible=!menu;if(intro>2.5){this.mala.position.set(this.hero.position.x,1.42,2.22);}else{this.mala.position.set(this.danav.position.x-.38,1.18+this.danav.userData.body.position.y,this.danav.position.z-.30);}this.mala.rotation.set(0,intro>2.5?0:this.danav.rotation.y,Math.sin(t*8)*.06);

 if(run&&!menu){if(run.stage!==this.stage)this.setStage(run.stage);const ids=new Set(run.objects.map(o=>o.id));for(const [id,m]of this.objects)if(!ids.has(id)){this.releaseObject(m);this.objects.delete(id)}for(const o of run.objects){let m=this.objects.get(o.id);if(!m){const pool=this.objectPool.get(o.type);m=pool?.pop()||this.templates[o.type].clone(true);m.userData={kind:o.type,burst:false};m.visible=true;m.rotation.set(0,0,0);m.position.set(o.lane*2.55,0,o.z);this.scene.add(m);this.objects.set(o.id,m)}m.position.z=o.z;if(o.done&&o.type==='coin'&&!m.userData.burst){m.userData.burst=true;for(let k=0;k<5&&this.particles.length<35;k++){const spark=new T.Mesh(this.sparkGeometry,this.sparkMaterial);spark.position.set(o.lane*2.55,o.y??.95,o.z);this.scene.add(spark);this.particles.push({m:spark,life:.4,v:new T.Vector3(Math.cos(k*1.25)*1.4,1+k*.15,Math.sin(k*1.25))});}}m.visible=!(o.done&&['coin','glide','shield','magnet'].includes(o.type));if(o.type==='shield'||o.type==='magnet'||o.type==='glide'){m.position.y=1.25+Math.sin(t*3)*.12;m.rotation.y=t*2;}if(o.type==='coin'){m.position.y=(o.y??.95)+Math.sin(t*3+o.id)*.06;m.rotation.y=t*1.6+o.id*.3;}}}for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;p.m.position.addScaledVector(p.v,dt);p.m.scale.setScalar(Math.max(0,p.life/.4));if(p.life<=0){this.scene.remove(p.m);this.particles.splice(i,1);}}if(this.qualityMode==='auto'&&!menu&&dt>0&&!intro){this.performanceFrames++;if(dt>.026)this.slowFrames++;if(this.performanceFrames>=180){if(this.slowFrames>65){this.renderer.setPixelRatio(Math.max(.8,this.renderer.getPixelRatio()-.25));this.renderer.shadowMap.enabled=false;this.resize();}this.performanceFrames=0;this.slowFrames=0;}}this.renderer.render(this.scene,this.camera);}
}
